-- Módulo 35 ConsumoMateriales: consumos reales de los componentes de una orden de producción.
-- Spec: docs/specs/modulo35-consumo-materiales-backend.md (§4).

CREATE TABLE "ConsumosMateriales" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "Numero" character varying(20) NOT NULL,
    "OrdenProduccionId" integer NOT NULL,
    "ComponenteProductoId" integer NOT NULL,
    "Cantidad" numeric(18,6) NOT NULL,
    "UnidadMedida" character varying(20) NOT NULL,
    "FechaRegistro" timestamp with time zone NOT NULL,
    "Responsable" character varying(100),
    "Observaciones" character varying(250),
    "Estado" character varying(10) NOT NULL,
    "FechaAnulacion" timestamp with time zone,
    "MotivoAnulacion" character varying(250),
    CONSTRAINT "PK_ConsumosMateriales" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_ConsumosMateriales_OrdenesProduccion_OrdenProduccionId"
        FOREIGN KEY ("OrdenProduccionId") REFERENCES "OrdenesProduccion" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_ConsumosMateriales_Productos_ComponenteProductoId"
        FOREIGN KEY ("ComponenteProductoId") REFERENCES "Productos" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_ConsumosMateriales_Cantidad" CHECK ("Cantidad" > 0),
    CONSTRAINT "CK_ConsumosMateriales_Estado" CHECK ("Estado" IN ('Registrado', 'Anulado'))
);

CREATE UNIQUE INDEX "IX_ConsumosMateriales_Numero" ON "ConsumosMateriales" ("Numero");
CREATE INDEX "IX_ConsumosMateriales_OrdenProduccionId" ON "ConsumosMateriales" ("OrdenProduccionId");
CREATE INDEX "IX_ConsumosMateriales_ComponenteProductoId" ON "ConsumosMateriales" ("ComponenteProductoId");
CREATE INDEX "IX_ConsumosMateriales_FechaRegistro" ON "ConsumosMateriales" ("FechaRegistro");
CREATE INDEX "IX_ConsumosMateriales_Estado" ON "ConsumosMateriales" ("Estado");
